  function setTool(next){tool=next;document.querySelectorAll('.tool').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));$('toolTitle').textContent=toolCopy[tool][0];$('toolHint').textContent=toolCopy[tool][1];svg.classList.toggle('draw-mode',!['select','erase','dimension'].includes(tool));$('furniturePanel').classList.toggle('hidden',tool!=='furniture');$('openingPanel').classList.toggle('hidden',!['door','window'].includes(tool));if(['door','window'].includes(tool)){$('openingTitle').textContent=tool==='door'?'門片圖例':'窗戶圖例';document.querySelectorAll('[data-opening]').forEach(b=>{const valid=tool==='door'?doorKinds.includes(b.dataset.opening):windowKinds.includes(b.dataset.opening);b.hidden=!valid;b.classList.toggle('active',valid&&b.dataset.opening===openingType)})}preview.innerHTML='';start=null}
