  svg.addEventListener('pointerdown',e=>{if(runHook('pointerdown',e))return;const p=point(e,true);if(tool==='select'){selected=null;editingRoomId=null;render();return}if(tool==='dimension'){createSizedRoom(p);return}if(tool==='door'||tool==='window'||tool==='furniture'){const room=roomAt(p),common={x:p.x,y:p.y,parentRoomId:room?.id||null,rotation:facilityRotation(room)};hooks.place.forEach(fn=>fn(common,tool,p,tool==='furniture'?furnitureType:openingType));if(tool==='door')addItem({type:'door',kind:doorKinds.includes(openingType)?openingType:'single',...common});if(tool==='window')addItem({type:'window',kind:windowKinds.includes(openingType)?openingType:'fixed',...common});if(tool==='furniture')addItem({type:'furniture',name:furnitureType,...common});return}if(['wall','room'].includes(tool)){start=p;svg.setPointerCapture(e.pointerId)}});
