  $('exportBtn').onclick=()=>{const copy=svg.cloneNode(true);copy.querySelector('#previewLayer').remove();copy.querySelectorAll('.vertex-handle').forEach(n=>n.remove());copy.querySelectorAll('.shape-editing').forEach(n=>n.classList.remove('shape-editing'));copy.setAttribute('xmlns',NS);const data=new XMLSerializer().serializeToString(copy),blob=new Blob([data],{type:'image/svg+xml'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(state.project||'房屋平面圖')+'.svg';a.click();URL.revokeObjectURL(a.href);toast('SVG 圖面已匯出')};
